package com.bank.advisor;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class DepositPlanFinder {

    private static final Logger log = Logger.getLogger(DepositPlanFinder.class.getName());

    public List<List<Integer>> combinationSum(int[] slabs, int target) {
        Arrays.sort(slabs);                            // enables early pruning
        List<List<Integer>> result = new ArrayList<>();
        backtrack(slabs, 0, target, new ArrayList<>(), result);
        log.info(() -> "Found " + result.size() + " deposit plans for target " + target);
        return result;
    }

    private void backtrack(int[] cand, int start, int remain,
                           List<Integer> path, List<List<Integer>> result) {
        if (remain == 0) { result.add(new ArrayList<>(path)); return; }
        for (int i = start; i < cand.length; i++) {
            if (cand[i] > remain) break;               // sorted ⇒ no further fits
            path.add(cand[i]);
            backtrack(cand, i, remain - cand[i], path, result); // i allows reuse
            path.remove(path.size() - 1);
        }
    }
}
