package com.bank.advisor;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CombinationSumDemo {

    private static final Logger log = Logger.getLogger(CombinationSumDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Recurring Deposit Plan Finder (Combination Sum)");
        int[] slabs = {2, 3, 5};   // deposit slabs in thousands
        int target = 8;            // goal in thousands
        DepositPlanFinder finder = new DepositPlanFinder();
        finder.combinationSum(slabs, target).forEach(p -> log.info("Plan: " + p));
    }
}
